   "sintesis": "La salida a bolsa de Anthropic podría dejar a la compañía con una amplia reserva de efectivo, pero también expone el circuito entre la empresa de IA y los proveedores que la financian y venden capacidad de cómputo. La empresa proyecta USD 220.000 millones en efectivo e inversiones de corto plazo, frente a compromisos de gasto cercanos a USD 900.000 millones.",
